SELECT table_name,COUNT(*) AS column_count FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('bottle_config','calibration_object','consumable_master','consumption_rule','dev_air_pump_model','dev_analyzer_model','dev_bench_reactor','dev_culture_container_spec','dev_detector_item','dev_detector_model','dev_floor_scale_model','dev_integrated_reactor','dev_peristaltic_pump_model','feed_medium','lab_air_pump','lab_balance','lab_bench_reactor','lab_bench_reactor_controller','lab_bench_reactor_controller_channel','lab_communication','lab_culture_container','lab_detection_rule','lab_detector','lab_detector_item_config','lab_downstream_device','lab_floor_scale','lab_integrated_reactor','lab_integrated_reactor_pump','lab_integrated_reactor_pump_config','lab_lab','lab_lab_leader','lab_peristaltic_pump','lab_printer','lab_printer_layout_setting','lab_relay','lab_sound_alarm','liquid_bag','sys_user_lab','lab_engineering_profile','lab_engineering_profile_version') GROUP BY table_name ORDER BY table_name;
SELECT c.connection_id FROM lab_bench_reactor_controller c LEFT JOIN sys_dict_data d ON d.dict_code=c.model_dict_code WHERE c.model_dict_code IS NOT NULL AND (d.dict_code IS NULL OR d.dict_type<>'smp_bench_controller_model' OR COALESCE(d.dict_level,0)<>1 OR COALESCE(d.parent_code,-1)<>0);
SELECT v.version_id FROM lab_engineering_profile_version v LEFT JOIN lab_engineering_profile p ON p.profile_id=v.profile_id WHERE p.profile_id IS NULL;
SELECT p.profile_id FROM lab_engineering_profile p LEFT JOIN lab_engineering_profile_version v ON v.version_id=p.current_version_id WHERE p.current_version_id IS NOT NULL AND (v.version_id IS NULL OR v.profile_id<>p.profile_id);
